//! Multimodal C bindings generated from the same local headers as the static library.
//! Raw calls require valid model/context lifetimes and serialized encoder evaluation.

// Names are the upstream C API. Keep layout tests generated by bindgen enabled.
#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]

include!(concat!(env!("OUT_DIR"), "/mtmd_bindings.rs"));

// Declared by hand so the generated allowlist (and the native build it is part of) stays unchanged.
extern "C" {
    /// KV positions a chunk occupies (an M-RoPE image uses fewer positions than tokens).
    pub fn mtmd_input_chunk_get_n_pos(chunk: *const mtmd_input_chunk) -> i32;
    /// Logger for mtmd and its CLIP encoder (it prints to stderr until one is set).
    pub fn mtmd_helper_log_set(
        log_callback: Option<crate::ffi::llama_cpp::LlamaLogCallback>,
        user_data: *mut std::ffi::c_void,
    );
}

// Audio generation (tools/mtmd/mtmd.h, mtmd-helper.h; upstream marks it experimental). Used only
// by native::speech, so an upstream change touches these declarations and that module.

/// `enum mtmd_gen_audio_type`: 0 = the projector cannot generate audio
pub const MTMD_GEN_AUDIO_TYPE_NONE: i32 = 0;
/// `MTMD_HELPER_GEN_AUDIO_OUTTYPE_PCM`: native mono F32 PCM (mtmd-helper.h enum's first value).
pub const MTMD_HELPER_GEN_AUDIO_OUTTYPE_PCM: i32 = 0;
/// `MTMD_HELPER_GEN_AUDIO_OUTTYPE_WAV`: 16-bit PCM WAV, mono
pub const MTMD_HELPER_GEN_AUDIO_OUTTYPE_WAV: i32 = 1;

/// `struct mtmd_gen_audio_info`
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct mtmd_gen_audio_info {
    pub type_: i32,
    pub sample_rate: i32,
    pub model_variant: *const std::ffi::c_char,
}

/// `struct mtmd_helper_gen_audio` (opaque)
#[repr(C)]
pub struct mtmd_helper_gen_audio {
    _private: [u8; 0],
}

/// `struct mtmd_helper_gen_audio_inp`
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct mtmd_helper_gen_audio_inp {
    pub seq_id: i32,
    pub prompt: *const std::ffi::c_char,
    pub prompt_len: usize,
    pub speaker_ref: *mut mtmd_bitmap,
    pub lang: *const std::ffi::c_char,
    pub top_k: i32,
    pub top_p: f32,
    pub seed: u32,
    pub out_type: i32,
}

extern "C" {
    pub fn mtmd_gen_audio_get_info(ctx: *const mtmd_context) -> mtmd_gen_audio_info;
    pub fn mtmd_helper_gen_audio_init(
        lctx: *mut std::ffi::c_void,
        mctx: *mut mtmd_context,
    ) -> *mut mtmd_helper_gen_audio;
    pub fn mtmd_helper_gen_audio_free(ctx: *mut mtmd_helper_gen_audio);
    pub fn mtmd_helper_gen_audio_set_input(
        ctx: *mut mtmd_helper_gen_audio,
        inp: *const mtmd_helper_gen_audio_inp,
    ) -> i32;
    /// >0: prompt tokens left, 0: done, <0: error
    pub fn mtmd_helper_gen_audio_step_prompt(ctx: *mut mtmd_helper_gen_audio, n_batch: i32) -> i32;
    /// One audio frame; `h_state_out` is null when no frame was made, `out_stop` set at the end
    pub fn mtmd_helper_gen_audio_step_gen(
        ctx: *mut mtmd_helper_gen_audio,
        sampled: i32,
        h_state_in: *const f32,
        h_state_out: *mut *const f32,
        out_stop: *mut bool,
    ) -> i32;
    pub fn mtmd_helper_gen_audio_get_output(
        ctx: *mut mtmd_helper_gen_audio,
        out_sample_rate: *mut i32,
        out_data: *mut *const std::ffi::c_char,
        out_data_len: *mut usize,
        out_n_samples: *mut i64,
    ) -> i32;
}

#[cfg(test)]
mod tests {
    use super::*;
    use cluaiz_core::media::{DecodedAudio, DecodedImage};
    use std::ptr::NonNull;
    use std::sync::Arc;

    struct Bitmap(NonNull<mtmd_bitmap>);

    impl Bitmap {
        fn bytes(&self) -> &[u8] {
            // SAFETY: this owner retains a non-placeholder bitmap for the borrowed slice.
            unsafe {
                std::slice::from_raw_parts(
                    mtmd_bitmap_get_data(self.0.as_ptr()),
                    mtmd_bitmap_get_n_bytes(self.0.as_ptr()),
                )
            }
        }
    }

    impl Drop for Bitmap {
        fn drop(&mut self) {
            // SAFETY: this pointer was allocated by mtmd and has one owner.
            unsafe { mtmd_bitmap_free(self.0.as_ptr()) }
        }
    }

    #[test]
    fn test_mtmd_image_copies_rgb_and_survives_source_drop() {
        for _ in 0..128 {
            let image = DecodedImage::new(2, 1, Arc::from([255, 0, 0, 0, 255, 0])).unwrap();
            // SAFETY: DecodedImage validates exact width * height * 3 byte length.
            let bitmap = Bitmap(
                NonNull::new(unsafe {
                    mtmd_bitmap_init(image.width(), image.height(), image.pixels().as_ptr())
                })
                .expect("native bitmap allocation"),
            );
            drop(image);
            assert_eq!(bitmap.bytes(), &[255, 0, 0, 0, 255, 0]);
            // SAFETY: the bitmap is live for all these queries.
            unsafe {
                assert_eq!(mtmd_bitmap_get_nx(bitmap.0.as_ptr()), 2);
                assert_eq!(mtmd_bitmap_get_ny(bitmap.0.as_ptr()), 1);
                assert!(!mtmd_bitmap_is_audio(bitmap.0.as_ptr()));
            }
        }
    }

    #[test]
    fn test_mtmd_audio_copies_pcm_and_native_defaults_link() {
        let samples = [0.25_f32, -0.5, 1.0];
        let audio = DecodedAudio::new(16000, 1, Arc::from(samples)).unwrap();
        // SAFETY: validated mono F32 data remains live through the native copying call.
        let bitmap = Bitmap(
            NonNull::new(unsafe {
                mtmd_bitmap_init_from_audio(audio.samples().len(), audio.samples().as_ptr())
            })
            .expect("native audio allocation"),
        );
        drop(audio);
        let expected: Vec<u8> = samples
            .iter()
            .flat_map(|sample| sample.to_ne_bytes())
            .collect();
        assert_eq!(bitmap.bytes(), expected);
        // SAFETY: bitmap is owned here; defaults/marker do not require a loaded model.
        unsafe {
            assert!(mtmd_bitmap_is_audio(bitmap.0.as_ptr()));
            let params = mtmd_context_params_default();
            assert!(params.n_threads > 0);
            assert!(!mtmd_default_marker().is_null());
            let chunks = NonNull::new(mtmd_input_chunks_init()).expect("native chunks allocation");
            assert_eq!(mtmd_helper_get_n_tokens(chunks.as_ptr()), 0);
            assert_eq!(mtmd_helper_get_n_pos(chunks.as_ptr()), 0);
            mtmd_input_chunks_free(chunks.as_ptr());
        }
    }
}
